package com.waze.gw;

import android.content.Context;

import java.io.InputStream;
import java.nio.charset.StandardCharsets;

/** Build metadata generated by the packaging scripts, with a safe source-build fallback. */
final class ModBuildInfo {
    private static final String VERSION_ASSET = "wz_mod_version.txt";
    private static final String CHANNEL_ASSET = "wz_build_channel.txt";
    private static final String OTA_BUILD_ID_ASSET = "wz_ota_build_id.txt";
    private static final String DEFAULT_VERSION = "Developer Build - Do not distribute";

    private ModBuildInfo() { }

    /** Source revision of the build ("abc12345", "-dirty" when uncommitted changes were built). */
    static String commit(Context context) {
        return line(context, "wz_build_commit.txt", 40, I18n.tr("settings.unknown"));
    }

    /** UTC time the packaging script ran. */
    static String builtAt(Context context) {
        return line(context, "wz_build_time.txt", 40, I18n.tr("settings.unknown"));
    }

    private static String line(Context context, String asset, int maxBytes, String fallback) {
        if (context == null) return fallback;
        InputStream input = null;
        try {
            input = context.getAssets().open(asset);
            byte[] buffer = new byte[maxBytes];
            int count = input.read(buffer);
            if (count <= 0 || input.read() != -1) return fallback;
            String value = new String(buffer, 0, count, StandardCharsets.UTF_8).trim();
            return value.length() == 0 ? fallback : value;
        } catch (Throwable ignored) {
            return fallback;
        } finally {
            if (input != null) try { input.close(); } catch (Throwable ignored) { }
        }
    }

    static String versionLabel(Context context) {
        if (context == null) return DEFAULT_VERSION;
        InputStream input = null;
        try {
            input = context.getAssets().open(VERSION_ASSET);
            byte[] buffer = new byte[128];
            int count = input.read(buffer);
            if (count <= 0 || input.read() != -1) return DEFAULT_VERSION;
            String value = new String(buffer, 0, count, StandardCharsets.UTF_8).trim();
            return value.length() == 0 ? DEFAULT_VERSION : value;
        } catch (Throwable ignored) {
            return DEFAULT_VERSION;
        } finally {
            if (input != null) try { input.close(); } catch (Throwable ignored) { }
        }
    }

    static String channel(Context context) {
        if (context == null) return "stable";
        InputStream input = null;
        try {
            input = context.getAssets().open(CHANNEL_ASSET);
            byte[] buffer = new byte[32];
            int count = input.read(buffer);
            if (count <= 0 || input.read() != -1) return "stable";
            String value = new String(buffer, 0, count, StandardCharsets.UTF_8).trim();
            return "reimei".equalsIgnoreCase(value) ? "reimei" : "stable";
        } catch (Throwable ignored) {
            return "stable";
        } finally {
            if (input != null) try { input.close(); } catch (Throwable ignored) { }
        }
    }

    static int otaBuildId(Context context) {
        if (context == null) return 0;
        InputStream input = null;
        try {
            input = context.getAssets().open(OTA_BUILD_ID_ASSET);
            byte[] buffer = new byte[24];
            int count = input.read(buffer);
            if (count <= 0 || input.read() != -1) return 0;
            int value = Integer.parseInt(new String(buffer, 0, count, StandardCharsets.UTF_8).trim());
            return Math.max(0, value);
        } catch (Throwable ignored) { return 0; }
        finally { if (input != null) try { input.close(); } catch (Throwable ignored) { } }
    }
}
